INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_LYCIAN','Lycian (Classical-Hellenistic Lycia)',-550,-30)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_BRYCE_LYCIANS','secondary scholarship','Bryce, Trevor R. The Lycians: A Study of Lycian History and Civilisation to the Conquest of Macedonia (Vol. 1, The Lycians in Literary and Epigraphic Sources)','Lycian history, language, and religion; the native Lycian pantheon and its Greek interpretatio')
INSERT INTO _e VALUES
 ('ENT_LYC_PANTHEON','Lycian Pantheon','collective','pantheon','Lycian','pantheon','B','Hub collective for the gods of the Lycians (SW Anatolia), attested in Lycian-language inscriptions and Greek/Latin sources; many figures are Luwian-derived and known largely through interpretatio Graeca.'),
 ('ENT_LYC_TRQQAS','Trqqas','deity','deity','Lycian','storm, sky, weather','B','Lycian storm/weather-god, the local continuation of Luwian/Anatolian Tarhunt (Tarhunz/Tarhunna); name attested in Lycian inscriptions, sometimes rendered Trqqñt.'),
 ('ENT_LYC_NATRI','Natri','deity','deity','Lycian','light, prophecy, healing','B','Lycian god equated with Apollo in the Greek/Lycian bilinguals; principal solar/oracular deity of Lycia, attested in coin legends and inscriptions.'),
 ('ENT_LYC_MALIYA','Maliya (Lycian)','deity','deity','Lycian','protection, oaths, civic order','B','Lycian goddess attested in inscriptions, often associated with Athena in interpretatio. HOMONYM: distinct local reflex of the existing Luwian Maliya (ENT_LUW_MALIYA), the broader Anatolian Maliya tradition.'),
 ('ENT_LYC_TWELVE_GODS','Lycian Twelve Gods (Dodeka Theoi)','collective','collective','Lycian','collective cult, civic protection','B','The ''Twelve Gods'' worshipped as a collective in Lycia and Pisidia, frequently depicted as twelve figures and invoked together in dedications and reliefs; a distinctively Anatolian grouping.'),
 ('ENT_LYC_ENI_MAHANAHI','Eni Mahanahi','deity','deity','Lycian','mother goddess, divine motherhood','B','''Mother of the Gods'' (eni mahanahi), the chief Lycian mother-goddess named in inscriptions; identified with the Anatolian Mother (Cybele) and locally with Leto, patron goddess of the Letoon sanctuary.'),
 ('ENT_LYC_KAKASBOS','Kakasbos','deity','deity','Lycian','protection, horsemanship, rural cult','C','Club-bearing rider-god of Lycia and Pisidia, attested on numerous Roman-era votive reliefs as a mounted figure wielding a club; assimilated to Heracles.'),
 ('ENT_LYC_SOZON','Sozon','deity','deity','Lycian','protection, salvation, horsemanship','C','Anatolian rider/savior god (''the Saviour'') venerated in Lycia, Pisidia and Phrygia on votive reliefs; closely related to the Kakasbos rider-god type and assimilated to Apollo/Helios in some dedications.');
