INSERT INTO entity_sources (entity_id,source_id,evidence_type,source_note)
INSERT INTO _p VALUES
 ('ENT_LYC_PANTHEON','PER_LYCIAN','Hub collective for the gods of the Lycians (SW Anatolia), attested in Lycian-language inscriptions and Greek/Latin sources; many figures are Luwian-derived and known largely through interpretatio Graeca.'),
 ('ENT_LYC_TRQQAS','PER_LYCIAN','Lycian storm/weather-god, the local continuation of Luwian/Anatolian Tarhunt (Tarhunz/Tarhunna); name attested in Lycian inscriptions, sometimes rendered Trqqñt.'),
 ('ENT_LYC_NATRI','PER_LYCIAN','Lycian god equated with Apollo in the Greek/Lycian bilinguals; principal solar/oracular deity of Lycia, attested in coin legends and inscriptions.'),
 ('ENT_LYC_MALIYA','PER_LYCIAN','Lycian goddess attested in inscriptions, often associated with Athena in interpretatio. HOMONYM: distinct local reflex of the existing Luwian Maliya (ENT_LUW_MALIYA), the broader Anatolian Maliya tradition.'),
 ('ENT_LYC_TWELVE_GODS','PER_LYCIAN','The ''Twelve Gods'' worshipped as a collective in Lycia and Pisidia, frequently depicted as twelve figures and invoked together in dedications and reliefs; a distinctively Anatolian grouping.'),
 ('ENT_LYC_ENI_MAHANAHI','PER_LYCIAN','''Mother of the Gods'' (eni mahanahi), the chief Lycian mother-goddess named in inscriptions; identified with the Anatolian Mother (Cybele) and locally with Leto, patron goddess of the Letoon sanctuary.'),
 ('ENT_LYC_KAKASBOS','PER_LYCIAN','Club-bearing rider-god of Lycia and Pisidia, attested on numerous Roman-era votive reliefs as a mounted figure wielding a club; assimilated to Heracles.'),
 ('ENT_LYC_SOZON','PER_LYCIAN','Anatolian rider/savior god (''the Saviour'') venerated in Lycia, Pisidia and Phrygia on votive reliefs; closely related to the Kakasbos rider-god type and assimilated to Apollo/Helios in some dedications.');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_LYC_TRQQAS','member_of','ENT_LYC_PANTHEON','high','Trqqas is the storm-god of the Lycian pantheon.'),
 ('ENT_LYC_NATRI','member_of','ENT_LYC_PANTHEON','high','Natri is a principal Lycian deity.'),
 ('ENT_LYC_MALIYA','member_of','ENT_LYC_PANTHEON','high','Lycian Maliya is a goddess of the Lycian pantheon.'),
 ('ENT_LYC_TWELVE_GODS','member_of','ENT_LYC_PANTHEON','high','The Twelve Gods are a collective cult within Lycian religion.'),
 ('ENT_LYC_ENI_MAHANAHI','member_of','ENT_LYC_PANTHEON','high','Eni Mahanahi, ''Mother of the Gods'', is the chief mother-goddess of the Lycian pantheon.'),
 ('ENT_LYC_KAKASBOS','member_of','ENT_LYC_PANTHEON','high','Kakasbos is a Lycian rider-god.'),
 ('ENT_LYC_SOZON','member_of','ENT_LYC_PANTHEON','high','Sozon is an Anatolian rider/savior god venerated in Lycia.'),
 ('ENT_LYC_TRQQAS','equated_with','ENT_LUW_TARHUNZ','high','Trqqas is the Lycian reflex of the Luwian storm-god Tarhunz (interpretatio across the Luwic continuum).'),
 ('ENT_LYC_TRQQAS','equated_with','ENT_HTT_TARHUNNA','medium','Trqqas continues the wider Anatolian storm-god Tarhunt, of which Hittite Tarhunna is the cognate.'),
 ('ENT_LYC_TRQQAS','equated_with','ENT_ZEUS','medium','As the chief Anatolian storm/sky-god, Trqqas was identified with Zeus in Greek interpretatio of Lycian cult.'),
 ('ENT_LYC_NATRI','equated_with','ENT_APOLLO','high','Natri is identified with Apollo in the Lycian-Greek bilingual inscriptions and coinage.'),
 ('ENT_LYC_MALIYA','aligned_with','ENT_LUW_MALIYA','medium','Lycian Maliya is a local reflex of the broader Anatolian/Luwian goddess Maliya; flagged as a homonymous but distinct cult.'),
 ('ENT_LYC_ENI_MAHANAHI','equated_with','ENT_CYBELE','high','Eni Mahanahi, ''Mother of the Gods'', corresponds to the Anatolian Mother Goddess Cybele.'),
 ('ENT_LYC_ENI_MAHANAHI','syncretized_with','ENT_LETO','medium','In Hellenized Lycia the mother-goddess of the Letoon was assimilated to Leto, mother of Apollo and Artemis.'),
 ('ENT_LYC_KAKASBOS','equated_with','ENT_HERACLES','high','The club-bearing rider-god Kakasbos was assimilated to Heracles in Roman-era Lycia and Pisidia.'),
 ('ENT_LYC_SOZON','equated_with','ENT_APOLLO','medium','The savior rider-god Sozon was identified with Apollo (Helios) in Anatolian votive dedications.'),
 ('ENT_LYC_SOZON','aligned_with','ENT_LYC_KAKASBOS','medium','Sozon and Kakasbos share the same Anatolian club-bearing rider-god iconographic type.'),
 ('ENT_LYC_KAKASBOS','aligned_with','ENT_ARES','low','As an armed warrior rider-god, Kakasbos is occasionally associated with martial deities such as Ares in regional cult, though Heracles is the primary equation.');
